window.CHALLENGES = {"noe":{"questions":[{"prompt":"¿Qué orden de hechos describe mejor el encargo de Noé?","options":["Recibió instrucciones, construyó y después entró con su familia","Entró al arca, recibió medidas y buscó materiales","Esperó el Diluvio y entonces decidió construir","Reunió a las familias vecinas antes de recibir instrucciones"],"hint":"Busca dónde comienza el mandato y dónde aparece la entrada en el arca."},{"prompt":"¿Qué diferencia la preparación de Noé de una reacción de último momento?","options":["Trabajó antes de que llegara el acontecimiento anunciado","Actuó únicamente cuando el agua ya había subido","Delegó toda decisión y se limitó a esperar","Cambió el diseño del arca según sus propios cálculos"],"hint":"La cronología entre Génesis 6 y 7 es importante."},{"prompt":"¿Por qué la constancia se observa mejor en acciones repetidas que en una promesa verbal?","options":["Porque la construcción exigía cumplir instrucciones a lo largo del tiempo","Porque Noé podía prever exactamente cada detalle del clima","Porque la familia conocía el resultado de antemano","Porque la tarea dejó de exigir esfuerzos pronto"],"hint":"Distingue entre una declaración de fe y un proceso de trabajo."},{"prompt":"¿Cuál es la inferencia más prudente sobre el lugar exacto de construcción?","options":["El relato utilizado no permite fijarlo con certeza","Fue necesariamente en una ciudad identificada por su nombre","Se construyó en el monte donde finalmente descansó","Se conoce por las ciudades mencionadas siglos después"],"hint":"Busca qué precisa la narración y qué no afirma."},{"prompt":"¿Qué evidencia de confianza sería más sólida al explicar el relato?","options":["Unir las instrucciones recibidas con la ejecución del trabajo","Suponer que la ausencia de dudas fue la causa decisiva","Atribuir el resultado a su reputación entre los vecinos","Afirmar que la tarea era sencilla por contar con ayuda"],"hint":"Compara los verbos de acción, no solo las cualidades descritas."},{"prompt":"¿Cuál interpretación evita añadir al texto detalles no comprobados?","options":["Reconocer la obediencia sin inventar fechas ni ubicaciones exactas","Asignar un calendario preciso a cada fase sin consultar el texto","Describir conversaciones privadas que el relato no registra","Convertir una suposición geográfica en dato bíblico seguro"],"hint":"Separa observación, inferencia e imaginación."}],"pearls":[{"prompt":"¿Qué tres etapas permiten distinguir la obediencia sostenida de un impulso de última hora?","hint":"Compara el encargo, el trabajo prolongado y los acontecimientos de Génesis 7.","answer":"Recibió instrucciones, construyó el arca y entró con su familia antes del Diluvio."},{"prompt":"¿Por qué la colaboración familiar no elimina la responsabilidad personal de Noé?","hint":"Reflexiona sobre quién recibe el encargo y quiénes participan en ejecutarlo.","answer":"Noé recibió el encargo y tomó acción; su familia colaboró en la preparación y en entrar al arca."},{"prompt":"¿Qué dato geográfico sería incorrecto afirmar con absoluta seguridad a partir de estos pasajes?","hint":"Verifica qué localizaciones se mencionan explícitamente y cuáles no.","answer":"No puede establecerse con certeza el lugar exacto donde se construyó el arca."}]},"abrahan":{"questions":[{"prompt":"¿Qué secuencia de lugares corresponde al viaje descrito?","options":["Ur, Harán y después Canaán","Canaán, Harán y después Ur","Ur, Jericó y después Filipos","Harán, Roma y después Canaán"],"hint":"Revisa el trayecto antes de centrarse en la promesa."},{"prompt":"¿Qué elemento del relato muestra que la confianza implicó una decisión práctica?","options":["Dejar una vida conocida para emprender el viaje","Recibir primero un plano completo de toda la ruta","Permanecer donde estaba hasta eliminar la incertidumbre","Buscar una garantía de que nunca habría contratiempos"],"hint":"Busca un cambio concreto en la forma de vivir."},{"prompt":"¿Por qué vivir en tiendas es significativo para comprender el relato?","options":["Refleja una vida itinerante tras abandonar su entorno anterior","Demuestra que no hizo preparativos antes de salir","Indica que todo el recorrido ocurrió en pocos días","Prueba que nunca volvió a encontrarse con otras personas"],"hint":"Relaciona vivienda, movimiento y etapa de vida."},{"prompt":"¿Qué conclusión sería excesiva al aplicar este ejemplo hoy?","options":["Que cualquier mudanza equivale a recibir una instrucción divina","Que confiar puede coexistir con preparar un cambio","Que la familia puede acompañarse durante la incertidumbre","Que algunas decisiones exigen salir de la comodidad"],"hint":"Distingue el encargo narrado de una regla universal."},{"prompt":"¿Cuál lectura explica mejor la relación entre promesa y acción?","options":["La promesa fue acompañada de un desplazamiento real","La promesa reemplazó por completo la necesidad de actuar","La acción ocurrió solo después de conocer todos los resultados","La confianza consistió en no conversar sobre las dificultades"],"hint":"Compara lo que se dijo con lo que luego ocurrió."},{"prompt":"¿Qué argumento está mejor sustentado por el texto base?","options":["Abrahán siguió el llamado aunque no controlaba todos los detalles del futuro","Abrahán ya conocía las rutas y sucesos exactos de los años siguientes","Sara permaneció definitivamente en Ur sin participar del camino","La narración afirma que todo cambio futuro será favorable"],"hint":"Evita completar silencios del texto con certezas propias."}],"pearls":[{"prompt":"¿Por qué el recorrido por Harán es más que un dato aislado de un mapa?","hint":"Examina el orden de los lugares y qué cambia al continuar el trayecto.","answer":"Conecta la salida desde Ur con la continuación hacia Canaán y muestra una transición real."},{"prompt":"¿En qué sentido confiar no equivale a conocer por anticipado todos los resultados?","hint":"Distingue la promesa que se relata de los detalles que permanecen abiertos.","answer":"Abrahán y Sara respondieron al llamado y siguieron viajando sin tener todas las respuestas sobre el futuro."},{"prompt":"¿Qué elemento del estilo de vida posterior permite comprobar que la decisión tuvo consecuencias materiales?","hint":"Busca una descripción de la forma de vivienda durante el recorrido.","answer":"Pasaron a vivir en tiendas mientras recorrían la tierra, lejos de la vida conocida en Ur."}]},"jose":{"questions":[{"prompt":"¿Qué relación existe entre la interpretación de los sueños y los graneros?","options":["La previsión permitió prepararse antes de los años difíciles","Los graneros se levantaron solo después de agotarse los alimentos","Los sueños describían únicamente asuntos familiares","El almacenamiento hizo innecesaria toda organización posterior"],"hint":"Busca las etapas entre anunciar y administrar."},{"prompt":"¿Qué dos ámbitos diferentes reúne la historia de José?","options":["Administrar recursos y afrontar el reencuentro familiar","Dirigir una guerra y explorar nuevos territorios","Aprender un idioma y negociar una boda","Construir un barco y organizar una travesía"],"hint":"Hay una dimensión pública y otra personal."},{"prompt":"¿Por qué los años de abundancia exigían disciplina?","options":["Porque reservar durante la bonanza protegía frente a una futura escasez","Porque la abundancia garantizaba que no habría crisis","Porque no había que distribuir alimento durante esos años","Porque José desconocía por completo lo anunciado"],"hint":"Piensa en decisiones tomadas antes del problema."},{"prompt":"¿Qué se puede inferir del encuentro con sus hermanos sin idealizarlo?","options":["El perdón no elimina automáticamente la historia del daño","La reconciliación implica negar los hechos del pasado","Los vínculos familiares no requieren ninguna conversación","El ejercicio de autoridad basta para reconstruir la confianza"],"hint":"Relaciona memoria, emociones y conducta."},{"prompt":"¿Cuál comparación es más precisa entre previsión y perdón?","options":["Ambas requieren actuar más allá de la reacción inmediata","Ambas dependen exclusivamente de tener abundancia material","Ambas consisten en evitar decisiones difíciles","Ambas garantizan que los demás cambiarán su conducta"],"hint":"Busca la conducta que precede al resultado."},{"prompt":"¿Qué enseñanza evita confundir una decisión prudente con una garantía absoluta?","options":["Prepararse reduce riesgos, pero no permite controlar cada circunstancia","Guardar recursos garantiza siempre el mismo desenlace","Perdonar obliga a renunciar a toda prudencia futura","Una interpretación correcta elimina todas las tensiones humanas"],"hint":"Observa los límites de lo que cuenta el relato."}],"pearls":[{"prompt":"¿Por qué interpretar correctamente un problema no era suficiente sin organizar una respuesta?","hint":"Relaciona la noticia sobre los años futuros con la gestión de recursos.","answer":"Se necesitaron reservas durante los años de abundancia para afrontar la escasez posterior."},{"prompt":"¿Cómo se relacionan el poder de José y la posibilidad de perdonar sin confundir ambos conceptos?","hint":"Compara la administración de Egipto con el reencuentro familiar.","answer":"José tuvo responsabilidad administrativa y, al encontrarse con sus hermanos, afrontó el daño del pasado con una respuesta que abrió lugar al perdón."},{"prompt":"¿Qué conclusión general sobre planificación sería demasiado absoluta aunque el resultado fuera favorable?","hint":"Un relato ejemplar no asegura que todas las circunstancias futuras se controlen.","answer":"Ser previsores ayuda, pero no garantiza eliminar todas las crisis ni conocer cada resultado."}]},"moises":{"questions":[{"prompt":"¿Qué amenaza percibieron los israelitas antes del cruce?","options":["La presión de quienes los perseguían cerca del mar","Una sequía de muchos años en Canaán","La falta de espacio para construir una ciudad","Un conflicto comercial con los fenicios"],"hint":"Sitúa la escena antes de cruzar, no después."},{"prompt":"¿Cuál secuencia expresa la tensión y el desenlace?","options":["Temor ante el peligro, instrucciones y paso por el mar","Paso por el mar, regreso a Egipto y salida inicial","Llegada a Canaán, enfrentamiento y construcción de barcas","Acuerdo con el faraón, fiesta y viaje por tierra firme"],"hint":"Distingue el problema inicial de la salida de él."},{"prompt":"¿Qué diferencia la calma activa de una simple negación del riesgo?","options":["Reconoce el peligro sin paralizarse ni inventar una solución humana","Afirma que el peligro nunca existió","Permite que la ansiedad sea el único criterio para actuar","Exige que todas las personas se sientan tranquilas enseguida"],"hint":"Piensa en cómo se responde al temor."},{"prompt":"¿Por qué no conviene usar este relato para prometer un desenlace idéntico hoy?","options":["Describe una intervención específica, no una fórmula para toda crisis","Porque el peligro relatado fue solo una metáfora","Porque el relato prohíbe tomar decisiones prácticas","Porque ninguna persona experimentó miedo aquella vez"],"hint":"Separa el hecho histórico relatado de la aplicación personal."},{"prompt":"¿Qué contraste ayuda a explicar el valor de la confianza?","options":["La situación parecía cerrada, pero el relato presenta un camino inesperado","El grupo conocía desde el comienzo cada etapa del resultado","La confianza evitó que apareciera cualquier amenaza","Todos actuaron sin necesitar orientación"],"hint":"Observa el escenario y cómo cambia."},{"prompt":"¿Cuál sería una afirmación excesiva sobre las emociones de los protagonistas?","options":["Que ninguno experimentó miedo durante la persecución","Que la situación los puso bajo presión","Que necesitaban orientación ante el peligro","Que el acontecimiento marcó su memoria colectiva"],"hint":"Busca si se mencionan reacciones de temor."}],"pearls":[{"prompt":"¿Cómo cambia el significado del miedo si ordenas los hechos antes y después de la intervención relatada?","hint":"La tensión inicial y el desenlace no pertenecen al mismo momento.","answer":"Ante la persecución y el mar los israelitas sintieron temor; el cruce cambió la situación que parecía sin salida."},{"prompt":"¿Por qué la calma no debe confundirse con negar la existencia de peligro?","hint":"Busca las señales de una amenaza real y cómo se responde a ella.","answer":"El peligro del perseguidor era real; se les pidió confianza y seguir orientación, no fingir que nada ocurría."},{"prompt":"¿Qué error cometeríamos si convirtiéramos una intervención excepcional en una garantía para todo problema?","hint":"Piensa en la diferencia entre un episodio histórico y una regla universal.","answer":"No corresponde prometer que cualquier crisis actual se resolverá de manera idéntica al cruce del mar."}]},"rahab":{"questions":[{"prompt":"¿Qué vínculo existe entre la casa de Rahab y su decisión?","options":["Su casa en la muralla fue un punto importante para proteger a los espías","La casa era únicamente un lugar de reunión de los gobernantes","La muralla no tuvo relevancia en el encuentro","Los espías llegaron cuando la ciudad ya estaba deshabitada"],"hint":"Localiza dónde se desarrollaron los hechos."},{"prompt":"¿Qué función tuvo el cordón escarlata en el relato?","options":["Sirvió como señal vinculada a un acuerdo y a su protección","Indicó la posición del palacio del rey","Era un adorno sin relación con la decisión de Rahab","Se utilizó como mapa para salir hacia el desierto"],"hint":"Busca el sentido de la señal, no solo su color."},{"prompt":"¿Por qué se considera que Rahab actuó con valentía?","options":["Tomó una decisión comprometida cuando había riesgos reales","Esperó hasta que todos los habitantes hicieran lo mismo","No necesitó decidir nada personalmente","Recibió una garantía de ausencia total de peligro"],"hint":"Identifica el costo de elegir antes del desenlace."},{"prompt":"¿Cuál inferencia distingue una promesa de una señal visible?","options":["La señal estaba ligada a instrucciones concretas que debían atenderse","Bastaba mostrar cualquier tela para obtener el mismo resultado","La señal eliminaba la necesidad de cumplir el acuerdo","El color fue elegido por las autoridades de Jericó para todas las casas"],"hint":"Compara el acuerdo con lo que se pidió hacer."},{"prompt":"¿Qué lectura evita reducir a Rahab a un simple objeto de rescate?","options":["Reconoce su iniciativa, su elección y sus acciones","Atribuye toda la decisión a los espías","Afirma que desconocía cualquier riesgo","Explica el episodio sin mencionar su conducta"],"hint":"Busca quién habla y toma decisiones."},{"prompt":"¿Qué conclusión está mejor ajustada a los límites de la narración?","options":["Su conducta tuvo consecuencias importantes; no conocemos cada pensamiento privado","Se registran todas las conversaciones mantenidas aquella noche","Se describe con exactitud lo que sentía a cada minuto","La narración permite reconstruir sin dudas todo su pasado"],"hint":"No conviertas una interpretación psicológica en una cita."}],"pearls":[{"prompt":"¿Qué relación debe existir entre una señal reconocible y el acuerdo que representa?","hint":"La señal por sí sola no explica las instrucciones asociadas.","answer":"El cordón escarlata estaba ligado al acuerdo con los espías y a la protección de su familia."},{"prompt":"¿Por qué el riesgo asumido por Rahab es central al interpretar su conducta?","hint":"Analiza qué estaba ocurriendo en Jericó cuando recibió a los visitantes.","answer":"Actuó a favor de los espías y de su familia en una ciudad bajo amenaza, afrontando consecuencias reales."},{"prompt":"¿Qué parte del relato demuestra que ella no fue simplemente una espectadora pasiva?","hint":"Busca quién facilita acciones, dialoga y toma decisiones.","answer":"Rahab recibió a los espías, colaboró en su protección y atendió las indicaciones sobre la señal."}]},"rut":{"questions":[{"prompt":"¿Qué secuencia conecta la lealtad de Rut con su nueva vida?","options":["Acompañó a Noemí y después trabajó espigando","Espigó en Belén y luego conoció por primera vez a Noemí","Fue reina antes de trasladarse a los campos","Trabajó para Booz antes de decidir acompañar a Noemí"],"hint":"Distingue el trayecto de los hechos en los campos."},{"prompt":"¿Qué práctica ayudó a Rut a sostenerse en su nueva situación?","options":["Recoger espigas durante la cosecha","Reclamar un puesto en el palacio","Dirigir una caravana militar","Vender las cosechas del rey"],"hint":"Observa el trabajo cotidiano y el entorno."},{"prompt":"¿Por qué la lealtad de Rut no se limita a palabras emotivas?","options":["Se tradujo en acompañamiento y esfuerzo sostenido","Consistió en prometer sin cambiar su situación","Eliminó por completo las dificultades de Noemí","Dependió de recibir una recompensa inmediata"],"hint":"Busca lo que hizo después de hablar."},{"prompt":"¿Qué aspecto del relato complementa la iniciativa personal de Rut?","options":["El trato protector que recibió en el campo de Booz","El hecho de que nunca necesitó apoyo de nadie","La ausencia total de dificultades económicas","El respaldo de una corte real en Belén"],"hint":"Una decisión propia y el apoyo ajeno pueden coexistir."},{"prompt":"¿Qué comparación resume mejor lealtad y cuidado comunitario?","options":["Rut se mantuvo junto a Noemí y otros facilitaron su seguridad","La lealtad solo puede demostrarse cuando hay abundancia","La protección vuelve innecesario el esfuerzo propio","El cuidado comunitario significa controlar todas las decisiones"],"hint":"Distingue acciones de diferentes personas."},{"prompt":"¿Qué afirmación excede lo que se puede extraer del episodio?","options":["Que toda persona leal recibirá idéntica ayuda y en el mismo tiempo","Que la lealtad puede expresarse con acciones concretas","Que los campos reflejan condiciones sociales de la época","Que Rut tomó decisiones en una situación incierta"],"hint":"Un relato particular no equivale a una garantía universal."}],"pearls":[{"prompt":"¿Cómo se conectan una promesa de compañía y el trabajo cotidiano de Rut en Belén?","hint":"Busca un acto de lealtad previo y una conducta posterior.","answer":"Rut decidió acompañar a Noemí y después espigó para contribuir a su sustento."},{"prompt":"¿Qué diferencia existe entre la iniciativa de Rut y la protección de Booz?","hint":"Observa acciones que nacen de personajes distintos.","answer":"Rut tomó la iniciativa de trabajar; Booz favoreció un entorno de protección en los campos."},{"prompt":"¿Qué lectura no sería justa con una persona necesitada a partir de este relato?","hint":"Una narración particular no fija el destino material de todas las personas.","answer":"No se puede concluir que toda persona leal obtendrá la misma clase de ayuda y en el mismo plazo."}]},"samuel":{"questions":[{"prompt":"¿Qué marco ayuda a entender la experiencia de Samuel?","options":["Su servicio en el santuario antes de aprender a reconocer la llamada","Su mando militar en una fortaleza","Su trabajo como comerciante en un puerto","Su participación en un tribunal romano"],"hint":"El lugar determina lo que estaba haciendo."},{"prompt":"¿Qué cambio se observa en su respuesta a lo que escuchaba?","options":["Pasó de no reconocer la situación a atender la orientación recibida","Reconoció desde el primer instante todos los detalles","Decidió ignorar para siempre lo que oyó","Pidió a otros que respondieran por él sin escuchar"],"hint":"Fíjate en la repetición y el aprendizaje."},{"prompt":"¿Por qué repetir una experiencia no siempre implica comprensión inmediata?","options":["Porque aprender exige interpretar correctamente lo que sucede","Porque todo mensaje repetido carece de valor","Porque Samuel ya tenía toda la información","Porque la atención se adquiere automáticamente con la edad"],"hint":"Compara escuchar un sonido y entenderlo."},{"prompt":"¿Qué papel cumple recibir orientación al comienzo de un aprendizaje?","options":["Ayuda a interpretar una situación que aún no se entiende bien","Sustituye para siempre la atención personal","Demuestra que no se necesita reflexionar","Garantiza que no habrá nuevos errores"],"hint":"Identifica quién ayuda al joven y cómo."},{"prompt":"¿Qué interpretación muestra mayor cuidado con el texto?","options":["Reconocer una etapa de aprendizaje sin suponer que todo fue fácil","Afirmar que Samuel comprendió sin ninguna ayuda","Sostener que la escena no incluyó incertidumbre","Convertir el relato en una promesa de oír voces literalmente hoy"],"hint":"No confundas el hecho narrado con una expectativa universal."},{"prompt":"¿Cuál es la diferencia central entre oír y escuchar activamente aquí?","options":["Escuchar implica disposición a comprender y responder","Oír obliga siempre a dar la primera respuesta posible","Escuchar significa no hacer preguntas nunca","Oír y escuchar son idénticos en toda circunstancia"],"hint":"Mira la conducta después de recibir explicación."}],"pearls":[{"prompt":"¿Qué diferencia muestran las llamadas repetidas entre percibir un mensaje y entenderlo?","hint":"Lee el diálogo como una progresión, no como episodios independientes.","answer":"Samuel oyó la llamada, al principio no entendió su origen y aprendió cómo responder."},{"prompt":"¿Por qué la intervención de quien orientaba a Samuel fue relevante para su aprendizaje?","hint":"Fíjate en cuándo logra interpretar mejor la experiencia.","answer":"Recibió ayuda para comprender lo que ocurría y responder de una manera apropiada."},{"prompt":"¿Qué lección sobre escuchar activamente se apoya en hechos y no solo en un lema?","hint":"Identifica el cambio observable en su respuesta.","answer":"Escuchar exige atención y disposición a actuar según lo comprendido, no solo detectar sonidos."}]},"jonatan":{"questions":[{"prompt":"¿Qué dos relaciones son centrales en el episodio?","options":["La amistad entre David y Jonatán y el apoyo durante la amenaza","El comercio entre Jonatán y Egipto","Una alianza entre Samuel y Booz","La rivalidad entre David y un mercader"],"hint":"Piensa en el vínculo que aparece en ambos pasajes."},{"prompt":"¿Qué acción permite reconocer la amistad como más que simpatía?","options":["Jonatán fortaleció a David en un momento de presión","Ambos evitaron hablar de asuntos difíciles","Jonatán exigió ser siempre el centro de atención","David recibió ayuda solo después de convertirse en rey"],"hint":"Busca una acción hacia la otra persona."},{"prompt":"¿Por qué esta amistad contrasta con la competencia por prestigio?","options":["Porque muestra apoyo en vez de intentar eclipsar al otro","Porque los dos compartían necesariamente idéntico futuro político","Porque nunca se encontraron en situaciones tensas","Porque la amistad exige renunciar a toda responsabilidad"],"hint":"Compara apoyo con rivalidad."},{"prompt":"¿Qué diferencia una promesa amistosa de la lealtad probada?","options":["La lealtad se demuestra cuando apoyar tiene un costo","Una promesa elimina automáticamente toda dificultad","La lealtad solo consiste en intercambiar regalos","Una amistad se valora únicamente por el tiempo transcurrido"],"hint":"Identifica el momento de mayor presión."},{"prompt":"¿Cuál lectura evita simplificar el contexto del vínculo?","options":["Reconocer la amistad en medio de tensiones reales de poder","Suponer que el entorno político no tuvo ninguna importancia","Afirmar que nunca hubo un riesgo alrededor de David","Interpretar todos los gestos como una negociación comercial"],"hint":"No olvides el escenario que rodea a los amigos."},{"prompt":"¿Qué inferencia está más apoyada por ambos textos?","options":["La amistad une afecto expresado y ánimo en la adversidad","La verdadera amistad elimina todo peligro","El apoyo solo existe cuando uno obtiene un beneficio","La lealtad requiere que ambos ocupen el mismo puesto"],"hint":"Relaciona los dos pasajes en vez de leer uno aislado."}],"pearls":[{"prompt":"¿Qué gesto de la amistad tiene mayor peso cuando David se encuentra bajo presión?","hint":"Busca acciones que fortalezcan al otro en un momento difícil.","answer":"Jonatán apoyó y fortaleció a David cuando este afrontaba amenazas."},{"prompt":"¿Por qué un vínculo amistoso puede ser leal aun con tensiones de poder alrededor?","hint":"No confundas las condiciones políticas con lo que hacen las dos personas.","answer":"Jonatán mostró afecto y respaldo a David en un contexto que podía favorecer la rivalidad."},{"prompt":"¿Qué prueba es mejor que un simple intercambio de declaraciones de amistad?","hint":"Investiga acciones realizadas en circunstancias exigentes.","answer":"El apoyo concreto en la adversidad da contenido a las promesas y al afecto expresado."}]},"abigail":{"questions":[{"prompt":"¿Qué hizo Abigaíl antes de hablar con David?","options":["Preparó provisiones y salió a su encuentro","Esperó hasta que David llegara al palacio","Convocó un juicio público contra su familia","Abandonó la región sin intervenir"],"hint":"Observa qué precede a las palabras."},{"prompt":"¿Qué problema intentaba evitar su intervención?","options":["Que una situación de ira terminara en violencia","Que un viaje comercial se retrasara por lluvia","Que se suspendiera una cosecha","Que David perdiera un concurso público"],"hint":"El riesgo principal no era económico solamente."},{"prompt":"¿Qué combinación explica la eficacia de su actuación?","options":["Rapidez práctica y palabras pronunciadas con tacto","Silencio prolongado y ausencia de preparativos","Mensajes agresivos acompañados de amenazas","Esperar a que otros resolvieran todo"],"hint":"Une un acto material y una forma de hablar."},{"prompt":"¿Por qué no basta con decir que Abigaíl «tenía razón»?","options":["Importaron también el momento, la manera y el riesgo que afrontó","Porque el relato evita registrar acciones concretas","Porque la intención no tuvo ninguna consecuencia","Porque la conversación ocurrió después de la crisis"],"hint":"Busca cómo una verdad puede comunicarse con prudencia."},{"prompt":"¿Qué lectura es más precisa sobre el autocontrol mostrado?","options":["Puede expresarse al intervenir para frenar una escalada, no solo al callar","Consiste siempre en no participar en conflictos de terceros","Garantiza que cualquier discurso tendrá éxito","Implica que no hace falta actuar con urgencia"],"hint":"Distingue pasividad de intervención prudente."},{"prompt":"¿Qué afirmación no está justificada por el episodio?","options":["Que siempre sea seguro acercarse personalmente a una persona violenta","Que sus palabras buscaron desactivar la ira","Que hizo preparativos antes del encuentro","Que el contexto exigía valorar consecuencias"],"hint":"El episodio no es una instrucción de seguridad universal."}],"pearls":[{"prompt":"¿Por qué las provisiones son importantes para comprender el diálogo posterior de Abigaíl?","hint":"Mira los preparativos hechos antes de acercarse a David.","answer":"Preparó provisiones y salió al encuentro, combinando ayuda práctica con palabras de tacto."},{"prompt":"¿Cómo interviene el autocontrol sin convertirse en silencio frente a un riesgo?","hint":"La intervención puede ser activa; examina a qué desenlace intentaba oponerse.","answer":"Abigaíl actuó y habló con prudencia para detener una escalada de ira y violencia."},{"prompt":"¿Qué elemento haría irresponsable recomendar que todos imiten literalmente su encuentro?","hint":"El relato no elimina los riesgos de conflictos actuales.","answer":"No sería seguro decir a cualquier persona que confronte cara a cara a alguien violento; hay que evaluar seguridad y buscar ayuda."}]},"salomon":{"questions":[{"prompt":"¿Qué petición distinguió a Salomón al comenzar su responsabilidad?","options":["Discernimiento para gobernar con justicia","Un ejército más grande como primer objetivo","Renunciar a escuchar casos difíciles","Aumentar inmediatamente sus propiedades"],"hint":"Lee qué pidió, no solo qué recibió."},{"prompt":"¿Qué ámbito pone a prueba esa petición en el relato general?","options":["Escuchar y juzgar asuntos humanos difíciles","Seleccionar rutas de comercio marítimo","Construir una muralla en Jericó","Aprender la navegación en el mar"],"hint":"Piensa en decisiones que afectan a otras personas."},{"prompt":"¿Por qué pedir sabiduría es diferente de reclamar tenerla?","options":["Reconoce la responsabilidad y la necesidad de guía","Afirma que los problemas ya están resueltos","Impide volver a consultar evidencias","Permite juzgar sin conocer el caso"],"hint":"Identifica qué actitud implica la petición."},{"prompt":"¿Qué límite debería recordarse al usar esta historia para tomar decisiones?","options":["Una petición de sabiduría no sustituye investigar los hechos de cada caso","La buena intención equivale automáticamente a un juicio exacto","Una persona sabia no necesita escuchar otras opiniones","Conocer la respuesta final evita analizar la situación"],"hint":"Separa cualidad personal y procedimiento."},{"prompt":"¿Cuál es la relación más sólida entre sabiduría y justicia?","options":["El juicio justo necesita discernimiento aplicado a personas concretas","La sabiduría solo importa para obtener prestigio","La justicia se alcanza ignorando emociones y circunstancias","La autoridad elimina la necesidad de escuchar pruebas"],"hint":"Relaciona capacidad y responsabilidad."},{"prompt":"¿Qué conclusión evita tratar el relato como una fórmula mágica?","options":["Buscar sabiduría implica cultivar decisiones responsables, no certeza infalible","Pedir ayuda hace imposible cometer errores futuros","Toda decisión difícil tiene una señal externa inmediata","La autoridad convierte cualquier conclusión en justa"],"hint":"Cuidado con expresiones absolutas que el texto no autoriza."}],"pearls":[{"prompt":"¿Qué reconoce indirectamente Salomón al pedir discernimiento para gobernar?","hint":"Piensa en lo que la petición presupone acerca de su responsabilidad.","answer":"Reconoce que necesita ayuda para tomar decisiones justas que afectan a su pueblo."},{"prompt":"¿Por qué la justicia exige más que tener autoridad para decidir?","hint":"Distingue posición social, información y buen juicio.","answer":"La autoridad no sustituye escuchar el caso, comprenderlo y aplicar discernimiento justo."},{"prompt":"¿Qué sería una interpretación demasiado literal del desenlace de su petición?","hint":"No conviertas el ejemplo en garantía infalible para cualquier persona.","answer":"No se puede concluir que pedir sabiduría haga imposible equivocarse en el futuro."}]},"viuda":{"questions":[{"prompt":"¿Con qué situación material comenzó el encuentro de la viuda?","options":["Recursos alimentarios extremadamente limitados","Reservas suficientes para muchos años","Una herencia recién recibida","Un suministro continuo administrado por el rey"],"hint":"El contexto inicial explica por qué la decisión pesaba."},{"prompt":"¿Qué dos acciones conectan necesidad y generosidad?","options":["Compartir en medio de la escasez y continuar el cuidado de su hogar","Guardar todo sin recibir a nadie","Vender una gran cosecha para adquirir tierras","Organizar un banquete para autoridades locales"],"hint":"Busca el tamaño real de los recursos iniciales."},{"prompt":"¿Por qué sería superficial decir simplemente «tenía mucho para dar»?","options":["Porque el relato resalta precisamente su situación de escasez","Porque desconocía por completo su propia necesidad","Porque el texto describe una despensa abundante","Porque la ayuda que dio no exigió confianza"],"hint":"Contrasta cantidad disponible con decisión."},{"prompt":"¿Qué interpretación aplica la generosidad con prudencia hoy?","options":["Reconocer el valor de compartir sin presionar a quien pasa necesidad","Exigir que toda familia entregue su último alimento","Prometer a toda persona un milagro material idéntico","Suponer que pedir apoyo es falta de fe"],"hint":"Un ejemplo concreto no debe convertirse en exigencia a otros."},{"prompt":"¿Qué aspecto hace significativa la confianza en este episodio?","options":["La decisión se produjo cuando el futuro material parecía inseguro","Solo compartió después de conseguir reservas para años","El resultado se conocía por experiencia propia desde antes","Las personas involucradas nunca sintieron necesidad"],"hint":"Sitúa la decisión antes del desenlace."},{"prompt":"¿Qué afirmación añade una garantía que el relato no da para cualquier época?","options":["Quien comparta alimentos siempre recibirá una provisión sobrenatural","La viuda estaba en una situación vulnerable","El relato vincula generosidad con confianza","La escasez forma parte del contexto del relato"],"hint":"Distingue el acontecimiento narrado de una ley general."}],"pearls":[{"prompt":"¿Qué hace más exigente el acto de compartir de la viuda de Sarepta?","hint":"Investiga cómo se describe la despensa antes del encuentro.","answer":"Tenía recursos muy limitados, de modo que compartir exigía confianza y generosidad en la escasez."},{"prompt":"¿Por qué la necesidad propia debe mencionarse cuando se narra su decisión?","hint":"Busca qué perderíamos del relato si omitiéramos la situación inicial.","answer":"Porque sin conocer la escasez se convertiría en una donación corriente y se perdería el peso de la decisión."},{"prompt":"¿Qué distinción evita usar esta historia para presionar a personas vulnerables?","hint":"Separa una acción voluntaria relatada de una obligación impuesta hoy.","answer":"La generosidad no autoriza exigir a quienes sufren que entreguen lo imprescindible para vivir."}]},"naaman":{"questions":[{"prompt":"¿Cuál fue la primera dificultad de Naamán ante la solución ofrecida?","options":["Aceptar una instrucción sencilla distinta de sus expectativas","Encontrar un ejército para cruzar un desierto","Aprender a gobernar en Samaria","Construir un templo antes del viaje"],"hint":"Contrasta lo esperado con lo pedido."},{"prompt":"¿Qué papel desempeñó el río Jordán en el relato?","options":["Fue el lugar relacionado con la instrucción que debía seguir","Sirvió solo de frontera política sin relación con la curación","Fue el sitio del primer encuentro con el rey","Aparece únicamente como referencia futura"],"hint":"Identifica dónde se esperaba que actuara."},{"prompt":"¿Por qué la humildad aparece después del conflicto de expectativas?","options":["Aceptar consejo exigió revisar la idea inicial de cómo debía ocurrir todo","Porque nadie propuso una alternativa clara","Porque la instrucción coincidía exactamente con sus preferencias","Porque el prestigio personal resolvió el problema"],"hint":"El obstáculo no era únicamente físico."},{"prompt":"¿Qué papel tienen los consejos de otras personas en esta historia?","options":["Ayudan a reconsiderar una reacción impulsiva ante lo inesperado","Reemplazan toda responsabilidad en la decisión final","Eliminan la necesidad de entender las instrucciones","Se ofrecen solo después de que acaba el episodio"],"hint":"Revisa a quiénes escuchó y cuándo."},{"prompt":"¿Qué lectura conserva el sentido del relato sin convertirlo en receta médica?","options":["Extraer una lección de humildad sin afirmar que el río cura enfermedades hoy","Aconsejar el baño en ese río como tratamiento universal","Atribuir a cualquier agua propiedades idénticas","Prescindir de atención sanitaria por analogía con la narración"],"hint":"Distingue el evento particular de una recomendación clínica."},{"prompt":"¿Qué contraste hace más complejo el episodio?","options":["La condición de Naamán y una instrucción que parecía demasiado simple","La necesidad de construir una obra pública gigantesca","Un problema que solo podía resolverse mediante prestigio","Un viaje emprendido sin ningún cuestionamiento previo"],"hint":"Mira cómo chocan orgullo y sencillez."}],"pearls":[{"prompt":"¿Qué característica de la instrucción recibida chocó con las expectativas de Naamán?","hint":"Busca por qué su reacción inicial fue negativa.","answer":"Era una instrucción sencilla relacionada con el Jordán, distinta de lo que él esperaba."},{"prompt":"¿Por qué escuchar a otras personas fue importante antes de decidir actuar?","hint":"Analiza el intervalo entre la reacción y el desenlace.","answer":"Los consejos le ayudaron a reconsiderar su negativa y a aceptar la orientación recibida."},{"prompt":"¿Qué generalización médica sería infundada aunque Naamán se curó?","hint":"Un caso particular no constituye evidencia de un tratamiento universal.","answer":"No se puede recomendar el agua del Jordán como cura médica general por este relato."}]},"jonas":{"questions":[{"prompt":"¿En qué ciudad se concentra la respuesta al mensaje de Jonás?","options":["Nínive","Jericó","Filipos","Belén"],"hint":"Identifica a los destinatarios de su advertencia."},{"prompt":"¿Qué dos escenas ayudan a comprender su cambio de perspectiva?","options":["La reacción de Nínive y la lección posterior de la planta","La construcción de un arca y un viaje a Egipto","El juicio del rey Salomón y el Jordán","El comienzo de la cosecha y el regreso de Noemí"],"hint":"El capítulo final no repite simplemente el anterior."},{"prompt":"¿Por qué no basta con estudiar solo el cambio de la ciudad?","options":["El texto también examina la reacción emocional de Jonás","Porque la ciudad no aparece en el relato","Porque Jonás nunca recibió ninguna orientación","Porque solo interesa el tamaño de sus murallas"],"hint":"Compara los capítulos 3 y 4."},{"prompt":"¿Qué tensión central muestra su actitud ante la misericordia?","options":["Esperaba un desenlace distinto del trato compasivo que se ofreció","Siempre se alegró espontáneamente de toda oportunidad de cambio","No comprendía el contenido del mensaje que dio","Su preocupación era exclusivamente económica"],"hint":"Fíjate en el contraste entre respuesta ajena y reacción propia."},{"prompt":"¿Qué interpretación es más fiel al uso de la planta?","options":["Es un recurso de enseñanza para revisar cómo Jonás valora las vidas ajenas","La planta demuestra que Nínive nunca escuchó","Su función principal fue localizar el puerto de salida","El relato la presenta como un premio por su alegría"],"hint":"Busca qué cuestionamiento surge al final."},{"prompt":"¿Qué aplicación evita una conclusión simplista sobre misericordia?","options":["Considerar a las personas más allá de nuestras primeras reacciones hacia ellas","Declarar que las malas decisiones carecen de consecuencias","Suponer que toda advertencia es innecesaria","Afirmar que el cambio de otras personas siempre ocurrirá de inmediato"],"hint":"Relaciona arrepentimiento, reacción y oportunidad."}],"pearls":[{"prompt":"¿Cómo contrasta la reacción de Nínive con el estado de ánimo posterior de Jonás?","hint":"Estudia la transición entre los capítulos 3 y 4.","answer":"Los habitantes de Nínive respondieron al mensaje; Jonás mostró dificultad para aceptar el trato misericordioso que recibieron."},{"prompt":"¿Por qué la planta añade algo nuevo después del cambio de la ciudad?","hint":"Fíjate en la pregunta moral final, no en los detalles botánicos.","answer":"La experiencia de la planta sirve para invitar a Jonás a reconsiderar qué y a quién valora."},{"prompt":"¿Qué error aparece al decidir de antemano que alguien no merece una nueva oportunidad?","hint":"El punto es la reacción del observador ante el cambio ajeno.","answer":"El relato invita a mostrar compasión hacia personas que cambian en vez de aferrarse al deseo de castigarlas."}]},"josias":{"questions":[{"prompt":"¿Qué hallazgo impulsó una revisión seria de la situación religiosa?","options":["El libro de la Ley hallado en el templo","Una carta comercial llegada de Egipto","Un nuevo mapa de la capital","Una lista de tributos extranjeros"],"hint":"El objeto encontrado contiene enseñanza, no recursos materiales."},{"prompt":"¿Qué secuencia explica la respuesta de Josías?","options":["Hallazgo, escucha del contenido y compromiso de cambio","Reforma completa, descubrimiento del texto y primera lectura","Salida al desierto, construcción del arca y regreso","Conquista militar, fiesta y juramento posterior"],"hint":"Observa el orden del capítulo 22 al 23."},{"prompt":"¿Qué distingue escuchar información de aprender verdaderamente en este caso?","options":["Dejar que lo leído transforme decisiones y conducta","Acumular documentos sin considerar su significado","Esperar que otro se responsabilice de todo","Usar la lectura solo para confirmar ideas previas"],"hint":"La etapa decisiva ocurre después de escuchar."},{"prompt":"¿Por qué es importante el momento de reacción del rey?","options":["Respondió a información que cuestionaba prácticas existentes","El documento no cambió ninguna decisión","El rey ignoró deliberadamente lo que se leyó","La reforma comenzó por asuntos exclusivamente arquitectónicos"],"hint":"Separa sorpresa, evaluación y respuesta."},{"prompt":"¿Qué evidencia sería más fuerte para describir aprendizaje auténtico?","options":["Relacionar la lectura pública con compromisos concretos posteriores","Citar la existencia de un libro sin mencionar consecuencias","Suponer que todos conocían ya cada línea del documento","Reducir el cambio a una emoción momentánea"],"hint":"Un conocimiento importante deja huella en acciones."},{"prompt":"¿Cuál aplicación evita imponer el contexto de Judá directamente a hoy?","options":["Revisar decisiones a la luz de buenos principios sin fingir tener el mismo cargo","Afirmar que todos deben realizar las mismas reformas políticas","Equiparar cualquier desacuerdo con infidelidad","Suponer que escuchar una lectura transforma a todos por igual"],"hint":"Considera la diferencia entre rey histórico y lector actual."}],"pearls":[{"prompt":"¿Qué distingue tener acceso a un libro de permitir que su contenido transforme decisiones?","hint":"Observa la conducta después del hallazgo y la lectura.","answer":"Josías escuchó lo que decía la Ley y promovió cambios acordes con lo aprendido."},{"prompt":"¿Por qué el orden hallazgo-lectura-respuesta importa en un análisis histórico?","hint":"Si se invierte el orden, cambia la causa del cambio.","answer":"El hallazgo permitió conocer el contenido y ese conocimiento desencadenó una respuesta posterior."},{"prompt":"¿Qué límite debe considerarse al aplicar decisiones de un rey antiguo al presente?","hint":"Revisa qué poderes y responsabilidades tenía en su época.","answer":"Podemos extraer una actitud de aprendizaje, pero no trasladar literalmente sus reformas políticas a nuestra situación."}]},"daniel":{"questions":[{"prompt":"¿Qué conflicto enfrentó Daniel en Babilonia?","options":["Presión legal relacionada con sus prácticas de oración","Falta de semillas para la cosecha","Disputa sobre el color de su ropa","Un problema de navegación en el mar"],"hint":"La tensión central pasa por una práctica regular."},{"prompt":"¿Qué continuidad muestra el relato antes y durante la presión?","options":["Mantuvo una costumbre de oración que ya practicaba","Inventó su conducta solo después de conocer el decreto","Cambió de ciudad para no ser observado","Abandonó inmediatamente todas sus responsabilidades"],"hint":"Busca qué se indica que hacía anteriormente."},{"prompt":"¿Por qué es importante la regularidad antes de la crisis?","options":["Muestra convicciones cultivadas y no solo reacción improvisada","Garantiza que nunca existirá oposición","Exime de considerar las consecuencias de cualquier decisión","Demuestra que todos los demás actuarán de la misma manera"],"hint":"Relaciona hábitos previos con presión posterior."},{"prompt":"¿Qué aspecto evita presentar a Daniel como alguien que buscaba conflicto?","options":["Su fidelidad se observa en continuar una práctica, no en provocar por provocar","Abandonó sus obligaciones para discutir con todos","Pidió que lo castigaran sin motivo","Modificó sus hábitos para llamar la atención pública"],"hint":"Distingue perseverancia y provocación."},{"prompt":"¿Qué afirmación sería injustificada al aplicar hoy el episodio?","options":["Que toda persona íntegra será librada físicamente de cualquier peligro","Que las convicciones pueden entrar en tensión con presiones externas","Que la perseverancia puede verse en hábitos","Que la historia muestra consecuencias serias de una decisión"],"hint":"No universalices el desenlace de un relato particular."},{"prompt":"¿Cuál diferencia es clave entre integridad y terquedad?","options":["La integridad se vincula a un principio sostenido y razonado","La integridad consiste en contradecir toda norma por sistema","La terquedad siempre termina en una buena consecuencia","Ambas se juzgan solo por la aprobación pública"],"hint":"Examina el fundamento de la conducta."}],"pearls":[{"prompt":"¿Qué diferencia su conducta bajo presión de una reacción improvisada?","hint":"Busca información sobre cómo actuaba antes del decreto.","answer":"Continuó su costumbre previa de orar a pesar de la presión legal."},{"prompt":"¿Cómo se distinguen integridad y provocación gratuita en este episodio?","hint":"Examina la continuidad de un hábito personal.","answer":"Daniel persistió en su práctica habitual por convicción; no necesitó inventar un acto para llamar la atención."},{"prompt":"¿Qué error supone prometer que todo creyente será protegido físicamente como Daniel?","hint":"Distingue un desenlace particular de una regla general.","answer":"El rescate narrado no garantiza que toda persona íntegra escape sin daño de todos los peligros."}]},"ester":{"questions":[{"prompt":"¿Por qué no era una decisión trivial presentarse ante el rey?","options":["La etiqueta de la corte implicaba riesgos reales para Ester","El protocolo permitía entrar siempre sin ser anunciada","Solo debía entregar un documento de comercio","No existía tensión respecto a su pueblo"],"hint":"El contexto jurídico y social de palacio importa."},{"prompt":"¿Qué secuencia aproxima la estrategia descrita?","options":["Preparación, acercamiento al rey y oportunidad de hablar","Denuncia pública, huida y regreso años después","Presentación del problema antes de conocer el riesgo","Solución inmediata sin necesidad de audiencia"],"hint":"Compara los capítulos 4, 5 y 7."},{"prompt":"¿Qué diferencia valentía de impulsividad en la historia?","options":["Actuó pese al riesgo y escogió cuidadosamente su oportunidad","Ignoró por completo el protocolo sin pensar","Esperó una garantía de ausencia total de peligro","Renunció a presentar su preocupación"],"hint":"La forma y el momento son parte de la decisión."},{"prompt":"¿Por qué el banquete no debe entenderse solo como celebración?","options":["Formó parte del contexto elegido para comunicar un asunto delicado","Sustituyó toda conversación sobre la amenaza","Fue una reunión casual sin efecto narrativo","Se organizó después de que todo estuviera resuelto"],"hint":"Busca qué revela Ester y cuándo."},{"prompt":"¿Qué combinación está mejor fundamentada por los pasajes?","options":["Valor para actuar y prudencia para elegir el momento","Temor que siempre impidió hablar","Acción sin información y sin preparación","Simple obediencia de otros sin decisión propia"],"hint":"Lee sus acciones y su secuencia como un conjunto."},{"prompt":"¿Cuál sería un uso imprudente de su ejemplo?","options":["Aconsejar que toda persona asuma riesgos idénticos sin evaluar su seguridad","Aprender a preparar una conversación difícil","Reconocer que el momento de hablar puede importar","Considerar cómo una decisión puede afectar a otros"],"hint":"La enseñanza histórica no sustituye un análisis de riesgos actual."}],"pearls":[{"prompt":"¿Por qué el contexto de acceso al rey importa antes de valorar el riesgo de Ester?","hint":"Investiga el protocolo de la corte y la razón de su vacilación.","answer":"Presentarse ante el rey sin autorización podía tener consecuencias serias para Ester."},{"prompt":"¿Qué relación existe entre esperar el momento oportuno y actuar con valentía?","hint":"Identifica decisiones preparatorias antes de la revelación del problema.","answer":"Ester se acercó al rey pese al riesgo, organizó encuentros y escogió el momento de exponer la amenaza."},{"prompt":"¿Qué interpretación sobre valor y prudencia evita una falsa oposición?","hint":"Compara riesgo, preparación y momento de hablar.","answer":"Su valor no excluyó la prudencia; ambos se complementaron en su estrategia."}]},"nehemias":{"questions":[{"prompt":"¿Qué hizo Nehemías antes de movilizar la reconstrucción?","options":["Inspeccionó los daños y evaluó el trabajo necesario","Anunció la obra terminada sin revisar el lugar","Demolió todos los muros restantes","Delegó la evaluación a visitantes que no conocían Jerusalén"],"hint":"La inspección aparece antes del trabajo organizado."},{"prompt":"¿Qué relación hay entre los diferentes grupos y la muralla?","options":["La tarea avanzó al distribuir y coordinar sectores de trabajo","Todo dependió de una única persona trabajando aislada","Los grupos se concentraron solamente en decorar puertas","Cada sector se diseñó sin relación con los demás"],"hint":"Revisa el capítulo que enumera los trabajos."},{"prompt":"¿Por qué la planificación no elimina la necesidad de perseverancia?","options":["Porque el trabajo encontró oposición y exigió continuidad","Porque una inspección hace innecesario construir","Porque los obstáculos desaparecen por completo antes de comenzar","Porque cooperar impide que aparezcan desacuerdos"],"hint":"La historia va más allá de repartir tareas."},{"prompt":"¿Qué diferencia una meta compartida de tareas improvisadas?","options":["Organización de responsabilidades alrededor de una obra común","Que nadie conoce la tarea del otro","Que todo se decide después de terminar","Que los trabajadores compiten por dificultar el avance"],"hint":"Conecta inspección, asignación y resultado."},{"prompt":"¿Qué afirmación se apoya mejor en el conjunto de pasajes?","options":["La cooperación incluyó diagnóstico, división del trabajo y constancia","La muralla surgió sin coordinación entre los participantes","La oposición demostró que el plan debía abandonarse","Las responsabilidades eran irrelevantes frente al entusiasmo"],"hint":"No leas solamente el final exitoso."},{"prompt":"¿Qué aplicación prudente evita idealizar el trabajo en equipo?","options":["Organizar tareas y resolver obstáculos sin prometer ausencia de conflictos","Suponer que todos los proyectos colaborativos terminarán igual","Eliminar la necesidad de revisar recursos y riesgos","Dejar todas las decisiones a quien hable más fuerte"],"hint":"Un ejemplo positivo no garantiza resultados idénticos."}],"pearls":[{"prompt":"¿Por qué inspeccionar antes de reconstruir es una decisión importante?","hint":"Observa qué necesitaba saber antes de coordinar a otros.","answer":"Inspeccionó los daños de la muralla para reconocer el alcance de la obra."},{"prompt":"¿Qué muestra el reparto de sectores sobre la cooperación?","hint":"Busca el capítulo con múltiples nombres y secciones de trabajo.","answer":"La reconstrucción dependió de muchas personas que asumieron partes concretas de una meta común."},{"prompt":"¿Por qué la existencia de oposición no invalida la planificación previa?","hint":"Compara el diagnóstico inicial con las dificultades del proceso.","answer":"El plan permitió organizar la obra; la oposición hizo necesaria perseverancia adicional, no mostró que planificar careciera de valor."}]},"maria":{"questions":[{"prompt":"¿Qué tipo de situación presentó el anuncio a María?","options":["Una responsabilidad inesperada que exigía reflexión y respuesta","Una decisión profesional con salario detallado","Una invitación política para dirigir Roma","Un traslado decidido previamente por toda la aldea"],"hint":"Mira qué clase de mensaje recibe."},{"prompt":"¿Qué actitud se reconoce mejor en sus palabras finales?","options":["Disponibilidad ante la responsabilidad recibida","Exigencia de controlar cada detalle futuro","Rechazo definitivo a escuchar más","Indiferencia hacia las consecuencias de la noticia"],"hint":"Distingue preguntar de negarse."},{"prompt":"¿Por qué una pregunta sincera no equivale necesariamente a falta de fe?","options":["Puede expresar deseo de comprender antes de actuar","Demuestra siempre desconfianza absoluta","Impide cualquier respuesta posterior","Significa que se conoce todo el futuro"],"hint":"Observa la conversación completa."},{"prompt":"¿Qué hace relevante el contraste entre anuncio y respuesta?","options":["La magnitud del anuncio no impidió una contestación reflexiva","María no tuvo ninguna decisión por tomar","La noticia era una tarea cotidiana sin consecuencias","La respuesta aparece antes de que se le informe algo"],"hint":"Piensa en la secuencia emocional e intelectual."},{"prompt":"¿Qué lectura evita proyectar detalles que Lucas no cuenta?","options":["Reconocer su disposición sin describir con certeza todas sus emociones íntimas","Afirmar conocer cada pensamiento durante el anuncio","Suponer que recibió un calendario de todos los sucesos futuros","Presentar una escena adicional como una cita literal"],"hint":"No confundas una posible interpretación con información explícita."},{"prompt":"¿Qué principio es más defendible al trasladar el episodio al presente?","options":["Afrontar una responsabilidad con humildad y preguntas sinceras","Esperar anuncios sobrenaturales idénticos antes de toda decisión","Abandonar la planificación de la vida cotidiana","Suponer que aceptar un reto elimina la incertidumbre"],"hint":"Aplica la actitud, no recrees literalmente las circunstancias."}],"pearls":[{"prompt":"¿Qué diferencia hay entre formular una pregunta sincera y rechazar una responsabilidad?","hint":"Analiza la conversación completa antes de juzgar el primer comentario.","answer":"María buscó comprender lo anunciado y finalmente mostró disposición a aceptar la responsabilidad."},{"prompt":"¿Por qué sería impreciso afirmar conocer todas las emociones de María durante el anuncio?","hint":"El texto registra sus palabras, pero no cada pensamiento íntimo.","answer":"Podemos describir sus preguntas y su respuesta, pero no reconstruir con certeza toda su experiencia emocional."},{"prompt":"¿Qué aspecto puede aplicarse hoy sin esperar una circunstancia idéntica?","hint":"Distingue el acontecimiento excepcional de una actitud general.","answer":"Humildad, escucha y disposición a asumir responsabilidades pueden inspirar decisiones presentes sin pretender recibir el mismo anuncio."}]},"samaritano":{"questions":[{"prompt":"¿Qué hecho transforma la historia en una prueba de compasión?","options":["La presencia de un viajero herido y la decisión de detenerse","La elección del camino más corto para un comerciante","La preparación de una fiesta en la ciudad","Un debate sobre rutas marítimas"],"hint":"Observa quién necesita ayuda y quién decide actuar."},{"prompt":"¿Qué secuencia refleja una ayuda completa en la parábola?","options":["Detenerse, cuidar al herido y procurar atención posterior","Mirar al herido y marcharse sin intervenir","Prometer apoyo sin ninguna acción","Ayudar solo si la víctima puede pagar de inmediato"],"hint":"La respuesta incluye más que un gesto instantáneo."},{"prompt":"¿Por qué el contraste entre personajes es importante?","options":["La proximidad al problema no garantizó una respuesta compasiva","Todos los viajeros respondieron de manera idéntica","La profesión de una persona determina siempre su bondad","El herido podía resolver solo toda la situación"],"hint":"Considera qué hicieron quienes pasaron."},{"prompt":"¿Qué amplía el significado de «prójimo» en la parábola?","options":["La ayuda se define por la conducta, no por la afinidad inicial","La compasión se reserva únicamente al círculo familiar","Ser prójimo depende de compartir el mismo lugar de origen","El título social determina quién merece cuidado"],"hint":"Mira cómo termina la conversación de Jesús."},{"prompt":"¿Cuál aplicación es prudente cuando hay una emergencia real?","options":["Ayudar de modo seguro y procurar apoyo apropiado para la persona afectada","Ignorar los riesgos de intervenir sin preparación","Negarse a pedir servicios profesionales","Confiar en que la intención basta para resolver cualquier lesión"],"hint":"La compasión puede incluir buscar ayuda competente."},{"prompt":"¿Qué lectura evita reducir el mensaje a una etiqueta religiosa?","options":["Valorar la acción concreta frente a la necesidad de otra persona","Suponer que basta pertenecer al grupo correcto","Describir la compasión sin mencionar al herido","Considerar importante solo el itinerario geográfico"],"hint":"El centro del relato es una respuesta ética visible."}],"pearls":[{"prompt":"¿Por qué la diferencia entre ver a alguien necesitado y ayudarlo es central?","hint":"Revisa qué hicieron las personas que pasaron junto al herido.","answer":"Algunos vieron y siguieron; el samaritano se detuvo, cuidó y buscó apoyo posterior."},{"prompt":"¿Qué detalle impide reducir la compasión a una emoción pasajera?","hint":"Busca acciones posteriores a la primera atención.","answer":"No solo sintió preocupación; organizó cuidados y apoyo para el viajero herido."},{"prompt":"¿Qué error puede surgir al imitar literalmente la intervención sin evaluar riesgos actuales?","hint":"Piensa en seguridad y atención profesional en una emergencia real.","answer":"La compasión exige actuar con seguridad, pedir ayuda competente cuando corresponda y no exponerse irresponsablemente."}]},"hijo":{"questions":[{"prompt":"¿Qué estructura de acontecimientos sostiene la parábola?","options":["Salida, deterioro de la situación y regreso","Regreso, salida y pérdida posterior","Fiesta inicial, herencia y viaje","Trabajo en casa, boda y viaje a Jerusalén"],"hint":"Identifica cómo cambia la condición del hijo."},{"prompt":"¿Qué dos reacciones familiares enriquecen la escena del regreso?","options":["La acogida del padre y la respuesta del hermano mayor","La respuesta de un rey y la de un comerciante","La opinión de los vecinos y la de un sacerdote","El consejo de un capitán y el de un juez"],"hint":"No te detengas cuando el hijo vuelve."},{"prompt":"¿Por qué arrepentimiento no equivale solamente a sentirse mal?","options":["Implica reconocer lo ocurrido y emprender el regreso","Significa olvidar las consecuencias sin admitir nada","Consiste en culpar únicamente al entorno","Obliga al padre a actuar antes de una decisión del hijo"],"hint":"Busca un cambio en dirección y conducta."},{"prompt":"¿Qué añade la reacción del hermano mayor al tema del perdón?","options":["Muestra que aceptar la restauración ajena puede ser difícil","Demuestra que el padre no interviene nunca","Vuelve irrelevante la decisión del hijo menor","Elimina toda tensión tras la celebración"],"hint":"Lee el final de la parábola, no solo la fiesta."},{"prompt":"¿Cuál inferencia considera de forma más completa las relaciones familiares?","options":["La reconciliación involucra al que regresa y las respuestas de los demás","El regreso borra todos los efectos del pasado sin conversación","El padre y ambos hijos sienten exactamente lo mismo","La historia presenta una fórmula para restaurar cualquier relación"],"hint":"Distingue los puntos de vista."},{"prompt":"¿Qué afirmación debe evitarse al aplicar la historia a relaciones dañinas hoy?","options":["Que perdonar obliga siempre a volver a una situación insegura","Que una persona puede reconocer sus errores","Que la acogida puede facilitar un nuevo comienzo","Que los familiares pueden sentir emociones distintas"],"hint":"El perdón y la seguridad personal requieren reflexión separada."}],"pearls":[{"prompt":"¿Qué cambia en el hijo desde la partida hasta el regreso?","hint":"Relaciona decisiones, consecuencias y reconocimiento del error.","answer":"Salió, atravesó dificultades, reconoció su situación y decidió regresar."},{"prompt":"¿Qué añade la reacción del hermano mayor a una lectura sobre el perdón?","hint":"El relato no termina con el abrazo y la celebración.","answer":"Muestra que la restauración del otro puede provocar resistencia en quienes observan la situación."},{"prompt":"¿Por qué perdón y seguridad no siempre se resuelven con una única frase?","hint":"Distingue el mensaje de la parábola de los riesgos de relaciones reales.","answer":"Perdonar no obliga automáticamente a restaurar una convivencia insegura; se pueden establecer límites."}]},"panes":{"questions":[{"prompt":"¿Qué contraste está en el centro del episodio?","options":["Una multitud grande y una provisión inicial muy limitada","Una multitud pequeña y un gran almacén real","Un problema de transporte y ausencia de viajeros","Una cosecha lista y falta de trabajadores"],"hint":"El contraste entre necesidad y recursos es decisivo."},{"prompt":"¿Qué detalle muestra atención a los recursos después de comer?","options":["Se recogieron los fragmentos sobrantes","Se abandonó todo lo que no se usó","Se repartieron únicamente monedas","Se ordenó construir nuevos graneros"],"hint":"La narración continúa después de repartir."},{"prompt":"¿Por qué el número reducido de alimentos es narrativamente importante?","options":["Hace visible la desproporción entre recursos y necesidad","Prueba que la multitud no tenía hambre","Indica que no se hizo ningún esfuerzo organizativo","Demuestra que el problema fue solo de reparto"],"hint":"Compara el inicio y el final de la escena."},{"prompt":"¿Qué lectura de la recogida de sobras está mejor sustentada?","options":["El cuidado de los recursos forma parte del desenlace","El milagro vuelve innecesario cuidar alimentos","Los restos se recogieron antes de que alguien comiera","Los discípulos no participaron en ninguna fase"],"hint":"No omitas los últimos versículos del relato."},{"prompt":"¿Cuál aplicación evita confundir el relato con una garantía automática?","options":["Compartir y administrar responsablemente sin prometer multiplicaciones milagrosas hoy","Dar por hecho que todo recurso limitado se hará infinito","Omitir la planificación cuando haya muchas personas","Suponer que la generosidad reemplaza toda logística"],"hint":"Separa la acción extraordinaria de principios cotidianos."},{"prompt":"¿Qué comparación une mejor el inicio y el cierre de la escena?","options":["Escasez inicial y atención posterior a lo que quedó","Abundancia inicial y pérdida total de alimentos","Ausencia de personas y celebración familiar","Pocas personas y almacenamiento en templos"],"hint":"Relee tanto los primeros como los últimos versículos."}],"pearls":[{"prompt":"¿Por qué el número de personas y la comida disponible deben leerse juntos?","hint":"Busca el contraste que se establece antes de repartir.","answer":"Una multitud necesitaba alimento y la provisión inicial era reducida, lo que subraya el alcance del acontecimiento."},{"prompt":"¿Qué principio de uso responsable de recursos aparece después de satisfacer la necesidad?","hint":"No dejes de leer cuando la gente ya ha comido.","answer":"Se recogieron los fragmentos sobrantes para no desperdiciar alimento."},{"prompt":"¿Qué interpretación distingue una lección actual de la intervención especial narrada?","hint":"Un resultado extraordinario no es una promesa automática sobre nuestros recursos.","answer":"Podemos aprender a compartir y cuidar alimentos sin esperar que los pocos recursos se multipliquen milagrosamente en toda ocasión."}]},"pedro":{"questions":[{"prompt":"¿Qué dos escenas construyen el arco de la historia de Pedro?","options":["Su negación bajo presión y una conversación posterior de restauración","Su elección como rey y su retiro político","Una larga peregrinación y un juicio comercial","La construcción del templo y un viaje marítimo"],"hint":"Se citan Lucas 22 y Juan 21 por una razón."},{"prompt":"¿Qué reacción personal aparece ligada al error cometido?","options":["Dolor al reconocer lo que había ocurrido","Celebración pública de su decisión","Indiferencia completa ante los hechos","Falta de recuerdo de lo sucedido"],"hint":"El relato no termina con el acto de negar."},{"prompt":"¿Por qué la restauración no puede reducirse a decir «nada pasó»?","options":["La conversación posterior reconoce la necesidad de recomenzar","Porque Pedro nunca se equivocó","Porque sus decisiones no tuvieron consecuencias personales","Porque la negación era desconocida para él"],"hint":"Conecta el pasado doloroso con el encuentro posterior."},{"prompt":"¿Qué diferencia arrepentimiento de quedarse atrapado en la culpa?","options":["Reconocer el error y aceptar una oportunidad de actuar mejor","Afirmar que el error no existió","Negarse a considerar cualquier responsabilidad futura","Suponer que una disculpa cambia automáticamente a los demás"],"hint":"Busca cambio y continuidad, no negación."},{"prompt":"¿Cuál interpretación evita exagerar lo que la restauración garantiza?","options":["Una segunda oportunidad puede abrir camino sin borrar la experiencia pasada","Toda falta tiene consecuencias inexistentes para siempre","Quien se arrepiente jamás vuelve a tener dificultades","Cualquier daño se repara de inmediato y sin esfuerzo"],"hint":"El relato no elimina la historia anterior."},{"prompt":"¿Qué aporta leer Lucas y Juan juntos?","options":["Contrastar el momento del fallo con la posibilidad posterior de recuperación","Suponer que ambos pasajes describen exactamente la misma escena","Concluir que la negación nunca tuvo lugar","Ignorar las emociones de Pedro durante la primera escena"],"hint":"Los dos pasajes muestran momentos distintos."}],"pearls":[{"prompt":"¿Qué aporta unir el relato de la negación con la conversación de Juan 21?","hint":"Cada pasaje ilumina un momento distinto de la experiencia.","answer":"El primero registra el fallo y el dolor de Pedro; el segundo muestra una oportunidad posterior de restauración."},{"prompt":"¿Por qué recuperar una relación no significa negar lo sucedido?","hint":"Busca por qué la conversación posterior tenía sentido.","answer":"La restauración ocurrió después de un error real que Pedro reconoció; no fue una declaración de que nada había pasado."},{"prompt":"¿Qué diferencia existe entre arrepentirse y vivir indefinidamente inmovilizado por la culpa?","hint":"Piensa en responsabilidad presente y futuro posible.","answer":"Arrepentirse incluye reconocer el daño y abrirse a una conducta distinta; no exige quedar paralizado para siempre."}]},"dorcas":{"questions":[{"prompt":"¿Qué evidencia concreta se usó para recordar la bondad de Dorcas?","options":["Prendas de vestir relacionadas con su ayuda a otros","Mapas de sus viajes comerciales","Documentos de un cargo militar","Joyas de la familia real"],"hint":"Observa qué mostraron las personas que la conocían."},{"prompt":"¿Qué tipo de impacto describe el relato?","options":["Obras de cuidado recordadas por la comunidad","Conquistas políticas de gran alcance","La construcción de una muralla","La creación de una ruta marítima"],"hint":"No todo impacto importante es público o grandioso."},{"prompt":"¿Por qué los objetos mostrados son más que detalles decorativos?","options":["Funcionan como evidencias de su dedicación a personas concretas","Demuestran exclusivamente su riqueza personal","Permiten conocer todas sus conversaciones privadas","Indican una profesión política oficial"],"hint":"Relaciona objetos con memoria comunitaria."},{"prompt":"¿Qué enseña la reacción de quienes conocían a Dorcas?","options":["La bondad persistente puede dejar huellas reales en otros","Las acciones de ayuda nunca son recordadas","Solo los grandes discursos tienen valor","La generosidad depende siempre del reconocimiento público"],"hint":"Piensa en el efecto de pequeñas acciones sostenidas."},{"prompt":"¿Cuál lectura evita inventar motivos privados que el texto no registra?","options":["Describir lo que hizo y cómo la recordaron sin afirmar conocer cada intención","Asegurar que buscaba fama por cada prenda","Concluir que nunca sintió cansancio","Deducir que todos sus días fueron idénticos"],"hint":"Separa acciones observables de pensamientos supuestos."},{"prompt":"¿Qué comparación ofrece una enseñanza válida hoy?","options":["La ayuda tangible suele ser recordada por sus beneficiarios","Solo cuentan los proyectos que alcanzan a miles","La bondad necesita recompensas visibles para existir","Una persona solidaria no puede tener dificultades"],"hint":"Busca qué destaca la comunidad, no cifras imaginadas."}],"pearls":[{"prompt":"¿Por qué mostrar prendas de vestir tiene valor como evidencia narrativa?","hint":"Los objetos están vinculados a personas que recibieron ayuda.","answer":"Las prendas recuerdan obras concretas de bondad de Dorcas y su impacto en la comunidad."},{"prompt":"¿Qué distingue una vida de servicio de una reputación basada solo en palabras?","hint":"Busca lo que otras personas podían enseñar físicamente.","answer":"La comunidad recordaba actos tangibles de ayuda, no únicamente afirmaciones sobre su carácter."},{"prompt":"¿Qué límite existe al interpretar las motivaciones íntimas de Dorcas?","hint":"Diferencia testimonios y objetos de pensamientos no registrados.","answer":"Podemos afirmar que practicó la bondad y fue recordada por ello, no asegurar conocer cada intención privada."}]},"lidia":{"questions":[{"prompt":"¿Qué entorno está asociado al primer encuentro con Lidia?","options":["Un lugar junto al río cerca de Filipos","El palacio de Nínive","Los muros de Jericó","Un campamento en el Sinaí"],"hint":"Fíjate en dónde se reunían para conversar."},{"prompt":"¿Qué dato sobre su actividad permite comprender su mundo cotidiano?","options":["Trabajaba en el comercio de púrpura","Era propietaria de un granero en Egipto","Construía barcos de pesca","Era una autoridad de la corte persa"],"hint":"El relato menciona su actividad económica."},{"prompt":"¿Por qué su hospitalidad es una decisión y no solo una etiqueta?","options":["Abrió su casa para recibir a otras personas","Únicamente expresó buenos deseos a distancia","Evitó toda relación con quienes conoció","Delegó la recepción de visitantes sin ofrecer espacio"],"hint":"Piensa en el uso concreto de su hogar."},{"prompt":"¿Qué relación existe entre escuchar y actuar en su historia?","options":["La acogida se produjo en el contexto de su respuesta al mensaje","Decidió alojar viajeros años antes de encontrarlos","Toda su actividad comercial terminó ese día","Sus visitantes nunca entraron en la ciudad"],"hint":"Compara el encuentro, la reacción y la casa."},{"prompt":"¿Qué interpretación conserva los límites de la fuente?","options":["Reconocer la hospitalidad de Lidia sin inventar el tamaño o riqueza de su hogar","Afirmar que el texto describe cada habitación de su casa","Asegurar que no tuvo más compromisos laborales","Especificar la cantidad exacta de visitantes de todas las ocasiones"],"hint":"El pasaje no es un inventario de propiedades."},{"prompt":"¿Qué aplicación es más razonable sin copiar literalmente su situación?","options":["Practicar una hospitalidad posible según los propios recursos y límites","Sentir obligación de alojar desconocidos sin medidas de seguridad","Suponer que todo acto hospitalario tiene costo cero","Creer que solo quienes trabajan con púrpura pueden ayudar"],"hint":"Distingue el principio de sus circunstancias concretas."}],"pearls":[{"prompt":"¿Por qué conocer el lugar junto al río es relevante para la historia de Lidia?","hint":"Sitúa el primer encuentro antes de describir lo que hizo en su casa.","answer":"Allí escuchó el mensaje en las cercanías de Filipos, antes de ofrecer hospitalidad."},{"prompt":"¿Qué vínculo se observa entre sus recursos cotidianos y la acogida de visitantes?","hint":"Relaciona una actividad laboral mencionada con una decisión personal.","answer":"Lidia era comerciante de púrpura y ofreció su casa, pero el texto no detalla todas sus posesiones."},{"prompt":"¿Qué aplicación de hospitalidad requiere tener en cuenta los límites de seguridad actuales?","hint":"El relato enseña un principio; no prescribe idéntico alojamiento a toda persona.","answer":"Podemos recibir y apoyar a otros según posibilidades y seguridad, sin exponer nuestro hogar irresponsablemente."}]}};
